        [AllowAnonymous]
        [HttpGet("m3u/canais")]
        public IActionResult GetCanaisM3U()
        {
            // BG-5: serve from dedicated file, not from config.xml
            var canaisFile = GetCanaisFilePath();
            if (!System.IO.File.Exists(canaisFile))
            {
                var config = GetConfig();
                if (!string.IsNullOrWhiteSpace(config.CanaisM3uContent))
                {
                    try
                    {
                        Directory.CreateDirectory(Path.GetDirectoryName(canaisFile)!);
                        System.IO.File.WriteAllText(canaisFile, config.CanaisM3uContent);
                        Log("M3U canais recriado a partir da configuracao em memoria.");
                    }
                    catch (Exception ex)
                    {
                        Log($"Falha ao recriar M3U canais a partir da configuracao: {ex.Message}");
                    }
                }

                if (!System.IO.File.Exists(canaisFile))
                {
                    Log("M3U canais requisitado mas arquivo nao encontrado.");
                    return NotFound("Nenhum dado de canais. Execute sincronizar primeiro.");
                }
            }
            var content = System.IO.File.ReadAllText(canaisFile);
            Log($"M3U canais servido ({content.Length / 1024}KB).");
            return Content(content, "application/x-mpegurl");
        }

