        private void RegisterXmlTvListingProvider(string guidePath, PluginConfiguration config)
        {
            var liveTvConfig = _configurationManager.GetConfiguration<LiveTvOptions>("livetv");
            var providers = liveTvConfig.ListingProviders.ToList();
            var provider = providers.FirstOrDefault(p =>
                string.Equals(p.Id, config.EpgListingProviderId, StringComparison.OrdinalIgnoreCase)
                || string.Equals(p.ListingsId, "Midia Storage Online EPG", StringComparison.OrdinalIgnoreCase));

            if (provider is null)
            {
                provider = new ListingsProviderInfo
                {
                    Id = Guid.NewGuid().ToString("N"),
                    Type = "xmltv"
                };
                providers.Add(provider);
            }

            provider.Type = "xmltv";
            provider.ListingsId = "Midia Storage Online EPG";
            provider.Path = guidePath;
            provider.EnableAllTuners = true;
            provider.EnabledTuners = Array.Empty<string>();
            provider.PreferredLanguage = "pt-BR";
            config.EpgListingProviderId = provider.Id;

            liveTvConfig.ListingProviders = providers.ToArray();
            _configurationManager.SaveConfiguration("livetv", liveTvConfig);
        }

        private static readonly object ManifestLock = new object();

        private Dictionary<string, string> LoadManifest()
        {
            var dir = Path.Combine(Plugin.AppPaths.ProgramDataPath, "midia-online");
            var path = Path.Combine(dir, "sync_manifest.json");
            lock (ManifestLock)
            {
                if (!System.IO.File.Exists(path))
                    return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                try
                {
                    var json = System.IO.File.ReadAllText(path);
                    return System.Text.Json.JsonSerializer.Deserialize<Dictionary<string, string>>(json) 
                           ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                }
                catch (Exception ex)
                {
                    Log($"Erro ao carregar manifesto: {ex.Message}. Criando novo.");
                    return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                }
            }
        }

        private void SaveManifest(Dictionary<string, string> manifest)
        {
            var dir = Path.Combine(Plugin.AppPaths.ProgramDataPath, "midia-online");
            Directory.CreateDirectory(dir);
            var path = Path.Combine(dir, "sync_manifest.json");
            lock (ManifestLock)
            {
                try
                {
                    var json = System.Text.Json.JsonSerializer.Serialize(manifest, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
                    System.IO.File.WriteAllText(path, json);
                }
                catch (Exception ex)
                {
                    Log($"Erro ao salvar manifesto: {ex.Message}");
                }
            }
        }

        private void NormalizeMidiaStorageOnlineTunerHost(string tunerUrl, string tunerId)
        {
            var liveTvConfig = _configurationManager.GetConfiguration<LiveTvOptions>("livetv");
            var tunerHosts = liveTvConfig.TunerHosts.ToList();
            var matchingHosts = tunerHosts
                .Where(h =>
                    string.Equals(h.Type, "m3u", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(h.Url, tunerUrl, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(h.FriendlyName, "Midia Storage Online (Canais)", StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (matchingHosts.Count == 0)
            {
                return;
            }

            var primary = matchingHosts.FirstOrDefault(h => string.Equals(h.Id, tunerId, StringComparison.OrdinalIgnoreCase)) ?? matchingHosts[0];
            primary.Id = tunerId;
            primary.Type = "m3u";
            primary.Url = tunerUrl;
            primary.FriendlyName = "Midia Storage Online (Canais)";
            primary.TunerCount = 0;
            primary.AllowHWTranscoding = true;
            primary.AllowStreamSharing = true;
            primary.EnableStreamLooping = false;
            primary.AllowFmp4TranscodingContainer = false;
            primary.FallbackMaxStreamingBitrate = 30000000;
            primary.IgnoreDts = true;
            primary.ReadAtNativeFramerate = false;

            var normalizedHosts = tunerHosts
                .Where(h =>
                    !(string.Equals(h.Type, "m3u", StringComparison.OrdinalIgnoreCase)
                      && string.Equals(h.Url, tunerUrl, StringComparison.OrdinalIgnoreCase)
                      && string.Equals(h.FriendlyName, "Midia Storage Online (Canais)", StringComparison.OrdinalIgnoreCase)))
                .ToList();
            normalizedHosts.Add(primary);
            liveTvConfig.TunerHosts = normalizedHosts.ToArray();
            _configurationManager.SaveConfiguration("livetv", liveTvConfig);
        }

        [HttpPost("sync")]
        public async Task<IActionResult> Sync([FromQuery] bool force = false, CancellationToken ct = default)
        {
            var config = GetConfig();
            if (string.IsNullOrEmpty(config.M3uUrl))
            {
                Log("Sync falhou: URL M3U nao configurada.");
                return BadRequest(new { error = "URL da lista M3U nao configurada." });
            }

            try
            {
                var sw = System.Diagnostics.Stopwatch.StartNew();
                Log($"Iniciando sync: baixando M3U de {config.M3uUrl}");
                MidiaStorageOnlineStreamProxy.LocalBaseUrl = _serverApplicationHost.GetSmartApiUrl(Request);
                string m3uRaw = null!;
                for (var attempt = 0; attempt <= 2; attempt++)
                {
                    try
                    {
                        using var httpClient = _httpClientFactory.CreateClient();
                        httpClient.Timeout = TimeSpan.FromMinutes(5);
                        httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36");
                        var resp = await httpClient.GetAsync(config.M3uUrl!).ConfigureAwait(false);
                        if (!resp.IsSuccessStatusCode)
                        {
                            Log($"Falha ao baixar M3U: HTTP {resp.StatusCode}");
                            if (attempt < 2)
                            {
                                await Task.Delay(2000 * (attempt + 1)).ConfigureAwait(false);
                                continue;
                            }
                            return BadRequest(new { error = $"Falha ao baixar M3U: HTTP {resp.StatusCode}" });
                        }
                        var bytes = await resp.Content.ReadAsByteArrayAsync().ConfigureAwait(false);
                        m3uRaw = Encoding.UTF8.GetString(bytes);
                        Log($"M3U baixado: {m3uRaw.Length / 1024}KB");
                        break;
                    }
                    catch (Exception ex) when (attempt < 2)
                    {
                        Log($"Download M3U falhou (tentativa {attempt + 1}/3): {ex.Message}. Retentando...");
                        await Task.Delay(2000 * (attempt + 1)).ConfigureAwait(false);
                    }
                }

                var entries = ParseM3u(m3uRaw, out var headerLine);
                entries = MidiaStorageOnlineEntryDeduplicator.DeduplicateByKey(entries, BuildEntryDedupKey).ToList();
                Log($"Entries deduplicadas: {entries.Count} entradas ativas.");
                Log($"M3U parsed: {entries.Count} entradas");

                if (entries.Count > 0)
                {
                    var s = entries[0];
                    Log($"Amostra 1: [{s.Type}] {s.Name} | URL: {s.Url}");
                }
                if (entries.Count > 1)
                {
                    var s = entries[1];
                    Log($"Amostra 2: [{s.Type}] {s.Name} | URL: {s.Url}");
                }
                if (entries.Count > 2)
                {
                    var s = entries[2];
                    Log($"Amostra 3: [{s.Type}] {s.Name} | URL: {s.Url}");
                }

                // 1. Processar e cadastrar os canais imediatamente apÃ³s o parse do M3U
                var channelEntries = entries
                    .Where(e => e.Type == "Canal")
                    .ToList();

                try
                {
                    await MidiaStorageOnlineLogoLibrary.EnsureChannelLogosAsync(
                        channelEntries,
                        $"{Request.Scheme}://{Request.Host}",
                        ct).ConfigureAwait(false);
                }
                catch (Exception logoEx)
                {
                    Log($"Falha ao resolver logos dos canais: {logoEx.Message}");
                }

                var canaisM3u = new StringBuilder();
                canaisM3u.Append(headerLine);
                foreach (var entry in channelEntries)
                {
                    AppendEntryLinesWithInferredTvgId(canaisM3u, entry);
                }

                // BG-5: save canais to dedicated file ONLY, do NOT serialize into config.xml
                var canaisContent = MidiaStorageOnlineStreamProxy.NormalizeM3uContent(canaisM3u.ToString());
                var canaisFilePath = GetCanaisFilePath();
                Directory.CreateDirectory(Path.GetDirectoryName(canaisFilePath)!);
                await System.IO.File.WriteAllTextAsync(canaisFilePath, canaisContent).ConfigureAwait(false);

                config.TotalChannelCount = entries.Count(e => e.Type == "Canal");
                config.EpgCompatibleChannelCount = entries.Count(e => e.Type == "Canal" && !string.IsNullOrWhiteSpace(GetEffectiveTvgId(e)));

                // Cadastrar/atualizar sintonizador imediatamente
                var tunerUrl = $"{Request.Scheme}://{Request.Host}/MidiaStorageOnline/m3u/canais";
                var tuner = new TunerHostInfo
                {
                    Id = config.TunerHostId,
                    Type = "m3u",
                    Url = tunerUrl,
                    FriendlyName = "Midia Storage Online (Canais)",
                    TunerCount = 0,
                    AllowHWTranscoding = true
                };
                var saved = await _tunerHostManager.SaveTunerHost(tuner).ConfigureAwait(false);
                config.TunerHostId = saved.Id;
                NormalizeMidiaStorageOnlineTunerHost(tunerUrl, saved.Id);

                var epgConfigured = !string.IsNullOrWhiteSpace(config.EpgUrl);
                if (config.EnableAutoEpg || epgConfigured)
                {
                    try
                    {
                        string? guidePath;
                        if (config.EnableAutoEpg)
                        {
                            guidePath = await AutoFetchEpgAsync(config, entries, ct).ConfigureAwait(false);
                        }
                        else
                        {
                            guidePath = await EnsureEpgGuideAsync(config, ct).ConfigureAwait(false);
                        }
                        if (!string.IsNullOrEmpty(guidePath))
                        {
                            RegisterXmlTvListingProvider(guidePath, config);
                        }
                    }
                    catch (Exception epgEx)
                    {
                        config.EpgLastError = epgEx.Message;
                        Log($"Falha ao sincronizar XMLTV/EPG: {epgEx.Message}");
                    }
                }
                else
                {
                    config.EpgLastError = null;
                }

                SaveConfig(config);
                Log($"Sintonizador M3U registrado no Live TV imediatamente: {tunerUrl} (ID: {saved.Id})");

                // 2. Criar pastas e preparar bibliotecas para filmes e series
                var strmPath = GetStrmOutputPath(config);
                var moviesPath = Path.Combine(strmPath, "Filmes");
                var seriesPath = Path.Combine(strmPath, "Series");

                Directory.CreateDirectory(moviesPath);
                Directory.CreateDirectory(seriesPath);
                _libraryMonitor.ReportFileSystemChangeBeginning(strmPath);

                try
                {
                    // Count upfront to create libraries before file processing
                    int entryMovieCount = entries.Count(e => e.Type == "Filme");
                    int entrySeriesCount = entries.Count(e => e.Type == "Serie");

                var existingLibs = _libraryManager.GetVirtualFolders().Select(v => v.Name).ToHashSet();

                if (!existingLibs.Contains("Filmes"))
                {
                    await _libraryManager.AddVirtualFolder("Filmes", CollectionTypeOptions.movies,
                        new LibraryOptions
                        {
                            PathInfos = new[] { new MediaPathInfo(moviesPath) },
                            PreferredMetadataLanguage = "pt",
                            MetadataCountryCode = "BR"
                        }, true).ConfigureAwait(false);
                    Log($"Biblioteca 'Filmes' criada apontando para {moviesPath}");
                }

                if (!existingLibs.Contains("Series") && entrySeriesCount > 0)
                {
                    await _libraryManager.AddVirtualFolder("Series", CollectionTypeOptions.tvshows,
                        new LibraryOptions
                        {
                            PathInfos = new[] { new MediaPathInfo(seriesPath) },
                            PreferredMetadataLanguage = "pt",
                            MetadataCountryCode = "BR"
                        }, true).ConfigureAwait(false);
                    Log($"Biblioteca 'Series' criada apontando para {seriesPath}");
                }

                    var manifest = force ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) : LoadManifest();
                    var newManifest = new System.Collections.Concurrent.ConcurrentDictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                    var createdDirs = new System.Collections.Concurrent.ConcurrentDictionary<string, byte>(StringComparer.OrdinalIgnoreCase);

                    var totalSynced = 0;
                    int movieCount = 0, seriesCount = 0, skippedCount = 0;

                // Loop paralelo somente para filmes e series
                    var movieAndSeriesEntries = entries.Where(e => e.Type == "Filme" || e.Type == "Serie").ToList();

                // BG-1: bounded parallelism
                await Parallel.ForEachAsync(movieAndSeriesEntries, new ParallelOptions { MaxDegreeOfParallelism = _maxParallelism }, async (entry, ct) =>
                {
                    if (entry.Type == "Filme")
                    {
                        var name = TruncatePathSegment(SanitizeName(entry.Name), MaxMovieFolderNameLength);
                        // ponytail: hash only the .strm name to keep folder names readable and still avoid collisions.
                        var fileName = TrimPathSegment(SanitizeName(entry.Name), MaxMovieFileStemLength);
                        var relPath = Path.Combine("Filmes", name, fileName + ".strm");
                        var filePath = Path.Combine(strmPath, relPath);
                        var newUrl = entry.Url.Trim();

                        newManifest.TryAdd(relPath, newUrl);

                        var fileExists = System.IO.File.Exists(filePath);
                        if (fileExists)
                        {
                            Log($"Sobrescrevendo .strm: {filePath}");
                        }

                        var dir = Path.Combine(moviesPath, name);
                        if (createdDirs.TryAdd(dir, 0))
                        {
                            Directory.CreateDirectory(dir);
                        }
                        await System.IO.File.WriteAllTextAsync(filePath, newUrl, ct).ConfigureAwait(false);
                        Interlocked.Increment(ref totalSynced);
                        Interlocked.Increment(ref movieCount);
                    }
                    else if (entry.Type == "Serie")
                    {
                        var showName = TruncatePathSegment(SanitizeName(entry.ShowName), MaxSeriesShowNameLength);
                        var seasonFolder = TruncatePathSegment(SanitizeName(entry.Season), MaxSeasonFolderNameLength);
                        // ponytail: hash only the .strm name to keep folder names readable and still avoid collisions.
                        var fileName = TrimPathSegment(SanitizeName(entry.Name), MaxEpisodeFileStemLength);
                        var relPath = Path.Combine("Series", showName, seasonFolder, fileName + ".strm");
                        var filePath = Path.Combine(strmPath, relPath);
                        var newUrl = entry.Url.Trim();

                        newManifest.TryAdd(relPath, newUrl);

                        var fileExists = System.IO.File.Exists(filePath);
                        if (fileExists)
                        {
                            Log($"Sobrescrevendo .strm: {filePath}");
                        }

                        var dir = Path.Combine(seriesPath, showName, seasonFolder);
                        if (createdDirs.TryAdd(dir, 0))
                        {
                            Directory.CreateDirectory(dir);
                        }
                        await System.IO.File.WriteAllTextAsync(filePath, newUrl, ct).ConfigureAwait(false);
                        Interlocked.Increment(ref totalSynced);
                        Interlocked.Increment(ref seriesCount);
                    }
                }).ConfigureAwait(false);

                // Smart cleanup: delete files that are no longer in the M3U
                var filesToDelete = manifest.Keys.Except(newManifest.Keys).ToList();
                var deletedCount = 0;
                foreach (var relPath in filesToDelete)
                {
                    var filePath = Path.Combine(strmPath, relPath);
                    // BG-4: delete-then-catch is O(1) I/O vs exists-then-delete which is O(2n)
                    try
                    {
                        System.IO.File.Delete(filePath);
                        deletedCount++;
                        // Try to delete empty parent directories up to moviesPath / seriesPath
                        var dir = Path.GetDirectoryName(filePath);
                        while (dir != null && dir.Length > strmPath.Length && Directory.Exists(dir) && !Directory.EnumerateFileSystemEntries(dir).Any())
                        {
                            Directory.Delete(dir);
                            dir = Path.GetDirectoryName(dir);
                        }
                    }
                    catch (FileNotFoundException) { /* already gone, skip */ }
                    catch (Exception ex)
                    {
                        Log($"Erro ao deletar arquivo obsoleto {relPath}: {ex.Message}");
                    }
                }

                // Save manifest
                var manifestToSave = new Dictionary<string, string>(newManifest, StringComparer.OrdinalIgnoreCase);
                SaveManifest(manifestToSave);

                config.LastSyncTime = DateTime.UtcNow;
                config.LastSyncDurationSeconds = sw.Elapsed.TotalSeconds;
                config.SyncedFileCount = totalSynced;
                config.LastSyncError = null;
                SaveConfig(config);

                Log($"Sync OK em {sw.Elapsed.TotalSeconds:F1}s: {totalSynced} salvos, {skippedCount} ignorados, {deletedCount} deletados, canais M3U {canaisM3u.Length / 1024}KB");

                await _activityManager.CreateAsync(new ActivityLog(
                    $"{totalSynced} .strm criados ({movieCount} filmes, {seriesCount} series)",
                    "MidiaStorageOnlineSync",
                    Guid.Empty)
                {
                    Overview = $"{skippedCount} ignorados, {deletedCount} deletados. Canais M3U: {canaisM3u.Length / 1024}KB"
                }).ConfigureAwait(false);

                return Ok(new
                {
                    fileCount = totalSynced,
                    movieCount,
                    seriesCount,
                    skippedCount,
                    deletedCount,
                    canaisKb = canaisM3u.Length / 1024,
                    message = $"{totalSynced} .strm salvos, {skippedCount} ignorados, {deletedCount} deletados. Canais disponiveis no Dashboard > TV ao Vivo."
                });
                }
                finally
                {
                    _libraryMonitor.ReportFileSystemChangeComplete(strmPath, true);
                    try
                    {
                        await UpdateLiveTvChannelItemsAsync(channelEntries, ct).ConfigureAwait(false);
                    }
                    catch (Exception refreshEx)
                    {
                        Log($"Falha ao atualizar canais Live TV após o sync: {refreshEx.Message}");
                    }
                }
            }
            catch (Exception ex)
            {
                Log($"Erro no sync: {ex.Message}");
                _logger.LogError(ex, "Sync error");
                config.LastSyncError = ex.Message;
                SaveConfig(config);
                return StatusCode(500, new { error = ex.Message });
            }
        }



        private string GetDefaultStrmPath() =>
            Path.Combine(Plugin.AppPaths.ProgramDataPath, "midia-online", "strm");

        private string GetStrmOutputPath(PluginConfiguration config)
        {
            if (!string.IsNullOrEmpty(config.StrmOutputPath))
                return config.StrmOutputPath;
            return GetDefaultStrmPath();
        }

        private List<M3uEntry> ParseM3u(string raw, out string headerLine)
        {
            var entries = new List<M3uEntry>();
            headerLine = "#EXTM3U\n";
            var lines = raw.Split('\n');

            if (lines.Length > 0 && lines[0].StartsWith("#EXTM3U", StringComparison.Ordinal))
                headerLine = lines[0].TrimEnd('\r') + "\n";

            string? currentExtinf = null;
            var currentLines = new List<string>();

            foreach (var line in lines)
            {
                var trimmed = line.Trim();
                if (trimmed.Length == 0) continue;

                if (trimmed.StartsWith("#EXTINF:", StringComparison.Ordinal))
                {
                    currentExtinf = line;
                    currentLines = new List<string> { line.TrimEnd('\r') + "\n" };
                }
                else if (trimmed.StartsWith('#'))
                {
                    if (currentExtinf != null)
                        currentLines.Add(line.TrimEnd('\r') + "\n");
                }
                else
                {
                    if (currentExtinf != null)
                    {
                        var cleanUrl = trimmed;
                        currentLines.Add(cleanUrl + "\n");
                        var entry = ParseEntry(currentExtinf, cleanUrl, currentLines);
                        entries.Add(entry);
                        currentExtinf = null;
                    }
                }
            }

            return entries;
        }

        private M3uEntry ParseEntry(string extinfLine, string url, List<string> rawLines)
        {
            string name = ExtractDisplayName(extinfLine);
            var tvgId = ExtractAttribute(extinfLine, "tvg-id");
            var tvgName = ExtractAttribute(extinfLine, "tvg-name");
            var groupTitle = ExtractAttribute(extinfLine, "group-title");
            var tvgLogo = ExtractAttribute(extinfLine, "tvg-logo");

            string type;
            if (IsMovieEntry(url))
                type = "Filme";
            else if (IsSeriesEntry(url))
                type = "Serie";
            else
                type = "Canal";

            if (type == "Canal")
            {
                tvgLogo = ResolveChannelLogo(tvgName, name, tvgId, tvgLogo);
            }

            string showName = name;
            string season = "Season 1";

            if (type == "Serie")
            {
                var epMatch = _epRegex.Match(name);
                if (epMatch.Success)
                {
                    showName = epMatch.Groups[1].Value.Trim();
                    season = "Season " + epMatch.Groups[2].Value;
                    var episodeTitle = epMatch.Groups[4].Value.Trim();
                    if (!string.IsNullOrEmpty(episodeTitle))
                        name = episodeTitle;
                }
            }

            return new M3uEntry
            {
                Name = name,
                Url = url,
                Type = type,
                RawLines = rawLines,
                ShowName = showName,
                Season = season,
                TvgId = tvgId,
                TvgName = tvgName,
                GroupTitle = groupTitle,
                TvgLogo = tvgLogo
            };
        }

        private static string SanitizeName(string name)
        {
            name = name.Replace(":", " - ", StringComparison.Ordinal);
            name = name.Replace("_", " - ", StringComparison.Ordinal);
            name = name.Replace("&", "e", StringComparison.Ordinal);

            var sb = new StringBuilder(name.Length);
            foreach (var c in name)
            {
                if (c == '\uFFFD' || char.IsControl(c) || _invalidFileNameChars.Contains(c))
                {
                    sb.Append('_');
                }
                else
                {
                    sb.Append(c);
                }
            }
            return Regex.Replace(sb.ToString().TrimEnd('.', ' '), @"\s+", " ").Trim();
        }

        private static string TrimPathSegment(string value, int maxLength)
        {
            value = string.IsNullOrWhiteSpace(value) ? "_" : value.Trim();
            if (value.Length <= maxLength)
            {
                return value;
            }

            var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)))[..10];
            var prefixLength = Math.Max(1, maxLength - hash.Length - 1);
            return value[..prefixLength].TrimEnd() + "_" + hash;
        }

        private static string TruncatePathSegment(string value, int maxLength)
        {
            value = string.IsNullOrWhiteSpace(value) ? "_" : value.Trim();
            return value.Length <= maxLength ? value : value[..maxLength].TrimEnd();
        }

        private static string BuildLegacyMovieRelativePath(M3uEntry entry, int folderMaxLength, int fileMaxLength)
        {
            var name = TrimPathSegment(SanitizeName(entry.Name), folderMaxLength);
            var fileName = TrimPathSegment(SanitizeName(entry.Name), fileMaxLength);
            return Path.Combine("Filmes", name, fileName + ".strm");
        }

        private static string BuildLegacySeriesRelativePath(M3uEntry entry, int showMaxLength, int seasonMaxLength, int fileMaxLength)
        {
            var showName = TrimPathSegment(SanitizeName(entry.ShowName), showMaxLength);
            var seasonFolder = TrimPathSegment(SanitizeName(entry.Season), seasonMaxLength);
            var fileName = TrimPathSegment(SanitizeName(entry.Name), fileMaxLength);
            return Path.Combine("Series", showName, seasonFolder, fileName + ".strm");
        }

        private static string BuildEntryDedupKey(M3uEntry entry)
        {
            if (string.Equals(entry.Type, "Filme", StringComparison.OrdinalIgnoreCase))
            {
                return $"Filme|{SanitizeName(entry.Name)}";
            }

            if (string.Equals(entry.Type, "Serie", StringComparison.OrdinalIgnoreCase))
            {
                return $"Serie|{SanitizeName(entry.ShowName)}|{SanitizeName(entry.Season)}|{SanitizeName(entry.Name)}";
            }

            var stableChannelKey = !string.IsNullOrWhiteSpace(entry.TvgId)
                ? entry.TvgId!.Trim()
                : NormalizeChannelDisplayName(entry.TvgName ?? entry.Name);

            return $"Canal|{stableChannelKey}|{entry.Url.Trim()}";
        }

        private static string ExtractDisplayName(string extinfLine)
        {
            if (string.IsNullOrEmpty(extinfLine))
                return "Unknown";

            bool inQuotes = false;
            int commaIdx = -1;
            int startIdx = 0;
            if (extinfLine.StartsWith("#EXTINF:", StringComparison.OrdinalIgnoreCase))
            {
                startIdx = "#EXTINF:".Length;
            }

            for (int i = startIdx; i < extinfLine.Length; i++)
            {
                char c = extinfLine[i];
                if (c == '"')
                {
                    inQuotes = !inQuotes;
                }
                else if (c == ',' && !inQuotes)
                {
                    commaIdx = i;
                    break;
                }
            }

            string name;
            if (commaIdx >= 0)
            {
                name = extinfLine.Substring(commaIdx + 1).Trim();
            }
            else
            {
                var lastQuote = extinfLine.LastIndexOf('"');
                if (lastQuote >= 0 && lastQuote < extinfLine.Length - 1)
                {
                    name = extinfLine.Substring(lastQuote + 1).Trim();
                }
                else
                {
                    name = extinfLine;
                    if (name.StartsWith("#EXTINF:", StringComparison.OrdinalIgnoreCase))
                    {
                        var match = Regex.Match(name, @"^#EXTINF:\s*[-+]?\d+\s*");
                        if (match.Success)
                        {
                            name = name.Substring(match.Length);
                        }
                    }
                    name = name.Trim();
                }
            }

            name = CleanLeftoverAttributes(name);
            return string.IsNullOrEmpty(name) ? "Unknown" : name;
        }

        private static string CleanLeftoverAttributes(string name)
        {
            if (string.IsNullOrEmpty(name))
                return name;

            var cleaned = name;
            cleaned = Regex.Replace(cleaned, @"\b(tvg-logo|tvg-name|tvg-id|group-title|tvg-country|tvg-language|tvg-chno|logo|channel-id)\s*=\s*""[^""]*""", "", RegexOptions.IgnoreCase);
            cleaned = Regex.Replace(cleaned, @"\b(tvg-logo|tvg-name|tvg-id|group-title|tvg-country|tvg-language|tvg-chno|logo|channel-id)\s*=\s*[^\s]*", "", RegexOptions.IgnoreCase);
            cleaned = Regex.Replace(cleaned, @"\s+", " ");
            cleaned = cleaned.Trim(' ', ',', '-', '_');
            return cleaned;
        }

        private static string GetEffectiveTvgId(M3uEntry entry)
        {
            var approvedTvgId = MidiaStorageOnlineApprovedChannelMappings.TryGetEpgId(entry.TvgName, entry.Name, entry.TvgId);
            if (!string.IsNullOrWhiteSpace(approvedTvgId))
            {
                return approvedTvgId;
            }

            var mappedTvgId = MidiaStorageOnlineChannelMappings.ResolveTvgId(
                entry.TvgId,
                entry.TvgName,
                entry.GroupTitle,
                entry.Name);

            if (!string.IsNullOrWhiteSpace(mappedTvgId))
            {
                return mappedTvgId;
            }

            return BuildSyntheticXmlTvId(entry.TvgName ?? entry.GroupTitle ?? entry.Name, entry.GroupTitle ?? entry.Name, null);
        }

        private static void AppendEntryLinesWithInferredTvgId(StringBuilder builder, M3uEntry entry)
        {
            if (entry.RawLines.Count == 0)
            {
                return;
            }

            var effectiveTvgId = GetEffectiveTvgId(entry);
            var firstLine = entry.RawLines[0];
            if (firstLine.StartsWith("#EXTINF:", StringComparison.OrdinalIgnoreCase))
            {
                if (entry.Type == "Canal")
                {
                    firstLine = NormalizeChannelExtinfLine(firstLine, entry);
                }

                if (!string.IsNullOrWhiteSpace(effectiveTvgId)
                    && string.IsNullOrWhiteSpace(entry.TvgId))
                {
                    firstLine = EnsureTvgIdAttribute(firstLine, effectiveTvgId, entry.TvgName, entry.GroupTitle);
                }
            }

            builder.AppendLine(firstLine);
            for (var i = 1; i < entry.RawLines.Count; i++)
            {
                var line = entry.RawLines[i].TrimEnd('\r', '\n');
                if (i == entry.RawLines.Count - 1 && entry.Type == "Canal")
                {
                    line = MidiaStorageOnlineStreamProxy.BuildProxyUrl(line);
                }

                builder.AppendLine(line);
            }
        }

        private static string NormalizeChannelExtinfLine(string extinfLine, M3uEntry entry)
        {
            var line = extinfLine;
            line = ReplaceExtinfAttribute(line, "tvg-name", entry.TvgName ?? entry.Name);
            line = ReplaceExtinfAttribute(line, "group-title", entry.GroupTitle);
            if (string.IsNullOrWhiteSpace(entry.TvgLogo))
            {
                line = RemoveExtinfAttribute(line, "tvg-logo");
            }
            else
            {
                line = ReplaceExtinfAttribute(line, "tvg-logo", entry.TvgLogo);
            }
            line = ReplaceExtinfDisplayName(line, entry.Name);
            return line;
        }

        private static string? NormalizeChannelLogo(string? logo)
        {
            if (string.IsNullOrWhiteSpace(logo))
            {
                return null;
            }

            if (!Uri.TryCreate(logo, UriKind.Absolute, out var uri))
            {
                return null;
            }

            if (!uri.Scheme.Equals(Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase)
                && !uri.Scheme.Equals(Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase))
            {
                return null;
            }

            if (uri.Host.Equals("aaa55.top", StringComparison.OrdinalIgnoreCase))
            {
                return null;
            }

            return logo.Trim();
        }

        private static string? ResolveChannelLogo(string? tvgName, string? name, string? tvgId, string? tvgLogo)
        {
            var approvedLogo = MidiaStorageOnlineApprovedChannelMappings.TryGetLogoUrl(tvgName, name, tvgId);
            if (!string.IsNullOrWhiteSpace(approvedLogo))
            {
                return approvedLogo;
            }

            var workbookLogo = MidiaStorageOnlineWorkbookLogoMappings.TryGetLogoUrl(tvgName, name, tvgId);
            if (!string.IsNullOrWhiteSpace(workbookLogo))
            {
                return workbookLogo;
            }

            return NormalizeChannelLogo(tvgLogo);
        }

        private static string ReplaceExtinfDisplayName(string extinfLine, string displayName)
        {
            var commaIndex = GetExtinfDisplayNameSeparatorIndex(extinfLine);
            if (commaIndex < 0)
            {
                return $"{extinfLine},{displayName}";
            }

            return extinfLine.Substring(0, commaIndex + 1) + displayName;
        }

        private static string ReplaceExtinfAttribute(string extinfLine, string attribute, string? value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return extinfLine;
            }

            var sanitizedValue = value.Replace("\"", "'");
            var quotedPattern = $@"\b{Regex.Escape(attribute)}\s*=\s*""[^""]*""";
            var unquotedPattern = $@"\b{Regex.Escape(attribute)}\s*=\s*[^\s,]+";

            if (Regex.IsMatch(extinfLine, quotedPattern, RegexOptions.IgnoreCase))
            {
                return Regex.Replace(
                    extinfLine,
                    quotedPattern,
                    $"{attribute}=\"{sanitizedValue}\"",
                    RegexOptions.IgnoreCase);
            }

            if (Regex.IsMatch(extinfLine, unquotedPattern, RegexOptions.IgnoreCase))
            {
                return Regex.Replace(
                    extinfLine,
                    unquotedPattern,
                    $"{attribute}=\"{sanitizedValue}\"",
                    RegexOptions.IgnoreCase);
            }

            var insertAt = extinfLine.IndexOf(',');
            if (insertAt < 0)
            {
                insertAt = extinfLine.Length;
            }

            return extinfLine.Insert(insertAt, $" {attribute}=\"{sanitizedValue}\"");
        }

        private static string RemoveExtinfAttribute(string extinfLine, string attribute)
        {
            var quotedPattern = $@"\s+\b{Regex.Escape(attribute)}\s*=\s*""[^""]*""";
            var unquotedPattern = $@"\s+\b{Regex.Escape(attribute)}\s*=\s*[^\s,]+";

            var cleaned = Regex.Replace(extinfLine, quotedPattern, string.Empty, RegexOptions.IgnoreCase);
            cleaned = Regex.Replace(cleaned, unquotedPattern, string.Empty, RegexOptions.IgnoreCase);
            cleaned = Regex.Replace(cleaned, @"\s{2,}", " ");
            return cleaned;
        }

        private static int GetExtinfDisplayNameSeparatorIndex(string extinfLine)
        {
            if (string.IsNullOrEmpty(extinfLine))
            {
                return -1;
            }

            var inQuotes = false;
            var startIdx = extinfLine.StartsWith("#EXTINF:", StringComparison.OrdinalIgnoreCase)
                ? "#EXTINF:".Length
                : 0;

            for (var i = startIdx; i < extinfLine.Length; i++)
            {
                var c = extinfLine[i];
                if (c == '"')
                {
                    inQuotes = !inQuotes;
                }
                else if (c == ',' && !inQuotes)
                {
                    return i;
                }
            }

            return -1;
        }

        private static string EnsureTvgIdAttribute(string extinfLine, string tvgId, string? tvgName, string? groupTitle)
        {
            var quotedPattern = @"\btvg-id\s*=\s*""[^""]*""";
            var unquotedPattern = @"\btvg-id\s*=\s*[^\s,]+";

            if (Regex.IsMatch(extinfLine, quotedPattern, RegexOptions.IgnoreCase))
            {
                extinfLine = Regex.Replace(
                    extinfLine,
                    quotedPattern,
                    $"tvg-id=\"{tvgId}\"",
                    RegexOptions.IgnoreCase);
            }
            else if (Regex.IsMatch(extinfLine, unquotedPattern, RegexOptions.IgnoreCase))
            {
                extinfLine = Regex.Replace(
                    extinfLine,
                    unquotedPattern,
                    $"tvg-id=\"{tvgId}\"",
                    RegexOptions.IgnoreCase);
            }
            else
            {
                var insertAt = extinfLine.IndexOf(',');
                if (insertAt < 0)
                {
                    insertAt = extinfLine.Length;
                }

                var attrs = new StringBuilder();
                attrs.Append($" tvg-id=\"{tvgId}\"");
                if (!string.IsNullOrWhiteSpace(tvgName) && !Regex.IsMatch(extinfLine, @"\btvg-name\s*=", RegexOptions.IgnoreCase))
                {
                    attrs.Append($" tvg-name=\"{tvgName}\"");
                }
                if (!string.IsNullOrWhiteSpace(groupTitle) && !Regex.IsMatch(extinfLine, @"\bgroup-title\s*=", RegexOptions.IgnoreCase))
                {
                    attrs.Append($" group-title=\"{groupTitle}\"");
                }

                return extinfLine.Insert(insertAt, attrs.ToString());
            }

            return extinfLine;
        }

        private static string BuildSyntheticXmlTvId(string site, string siteId, string? feed)
        {
            var parts = new[] { site, siteId, feed }
                .Where(p => !string.IsNullOrWhiteSpace(p))
                .Select(p => p!.Trim().ToLowerInvariant());

            var raw = string.Join("_", parts);
            var sb = new StringBuilder(raw.Length);
            foreach (var ch in raw)
            {
                sb.Append(char.IsLetterOrDigit(ch) ? ch : '_');
            }

            var normalized = Regex.Replace(sb.ToString(), "_+", "_").Trim('_');
            return string.IsNullOrWhiteSpace(normalized) ? Guid.NewGuid().ToString("N") : normalized;
        }

        private static bool IsMovieEntry(string url)
        {
            return url.Contains("/movie/", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsSeriesEntry(string url)
        {
            return url.Contains("/series/", StringComparison.OrdinalIgnoreCase);
        }

        private static string? ExtractAttribute(string extinfLine, string attribute)
        {
            if (string.IsNullOrEmpty(extinfLine))
            {
                return null;
            }

            var match = Regex.Match(extinfLine, $@"\b{Regex.Escape(attribute)}\s*=\s*""([^""]*)""", RegexOptions.IgnoreCase);
            if (match.Success)
            {
                return match.Groups[1].Value;
            }

            match = Regex.Match(extinfLine, $@"\b{Regex.Escape(attribute)}\s*=\s*([^\s,]+)", RegexOptions.IgnoreCase);
            return match.Success ? match.Groups[1].Value : null;
        }

        private class M3uEntry : IMidiaStorageOnlineM3uEntry
        {
            public string Name { get; set; } = "";
            public string Url { get; set; } = "";
            public string Type { get; set; } = "Canal";
            public string ShowName { get; set; } = "";
            public string Season { get; set; } = "Season 1";
            public List<string> RawLines { get; set; } = new();
            public string? TvgId { get; set; }
            public string? TvgName { get; set; }
            public string? GroupTitle { get; set; }
            public string? TvgLogo { get; set; }
        }
    }
}
